import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {actionsWorkflowsAppBuilder} from './config/app-builder'

import {workflowsLayoutRoute} from './routes/workflows-layout-route'
import {WorkflowsLayout} from './routes/workflows-layout'

import {allWorkflowRunsRoute} from './routes/all-workflow-runs-route'
import {AllWorkflowRuns} from './routes/all-workflow-runs'

import {workflowRunsRoute} from './routes/workflow-runs-route'
import {WorkflowRuns} from './routes/workflow-runs'

export const actionsWorkflowsApp = actionsWorkflowsAppBuilder.createDataRouterAppFromRoutes([
  workflowsLayoutRoute.toRoute({
    Component: WorkflowsLayout,
    children: [
      allWorkflowRunsRoute.toRoute({Component: AllWorkflowRuns}),
      workflowRunsRoute.toRoute({Component: WorkflowRuns}),
    ],
  }),
])
registerDataRouterApp(actionsWorkflowsApp)
