import {mainQuery} from '@github-ui/react-core/future/main-query'
import {actionsWorkflowsAppBuilder} from '../config/app-builder'
import type {Workflow} from '../views/models'

export type WorkflowsLayoutPayload = {
  workflows: Workflow[]
  totalCount: number
  pinnedWorkflowIds: number[]
  allowPinning: boolean
  showDeployments: boolean
  showAttestations: boolean
  showRunners: boolean
  showUsageMetrics: boolean
}

export const workflowsLayoutRoute = actionsWorkflowsAppBuilder.createQueryRouteConfig('workflowsLayoutRoute', {
  path: '/:owner/:repo/actions',
  queries: [
    mainQuery<WorkflowsLayoutPayload>({
      queryDeps: ({pathname}) => ({pathname: `${pathname}/_layout`}),
      staleTimeForNavigation: 360000,
    }),
  ],
})
