import {mainQuery} from '@github-ui/react-core/future/main-query'
import {actionsWorkflowsAppBuilder} from '../config/app-builder'
import type {WorkflowRun} from '../views/models'

export type AllWorkflowRunsResponse = {
  workflowRuns: WorkflowRun[]
  reactToggle: string
  pinnedWorkflowIds: number[]
  repoBlocked: boolean
  userBlocked: boolean
  showOnlyRequiredWorkflows: boolean
  showActionsNotEnabledBanner: boolean
}

export const allWorkflowRunsRoute = actionsWorkflowsAppBuilder.createQueryRouteConfig('allWorkflowRunsRoute', {
  path: '/:owner/:repo/actions',
  queries: [mainQuery<AllWorkflowRunsResponse>()],
})
