import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Outlet, useParams} from '@github-ui/react-router'
import {Button, Heading, PageLayout} from '@primer/react'
import {WorkflowSidebar} from '../components/WorkflowSidebar'
import {workflowsLayoutRoute} from './workflows-layout-route'
import styles from './workflows-layout.module.css'

export function WorkflowsLayout() {
  const {data: payload, refetch} = useRouteQuery(workflowsLayoutRoute, 'mainQuery')
  const {owner = '', repo = '', filename} = useParams()

  return (
    <div className={styles.layout}>
      <PageLayout containerWidth="full" columnGap="condensed" padding="condensed">
        <PageLayout.Pane position="start" divider="line" width="medium" sticky>
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginTop: 4,
              marginBottom: 8,
              paddingLeft: 16,
              paddingRight: 8,
            }}
          >
            <Heading as="h2" variant="medium">
              Actions
            </Heading>
            <Button as="a" href={`/${owner}/${repo}/actions/new`} variant="primary" size="small">
              New workflow
            </Button>
          </div>
          <WorkflowSidebar
            workflows={payload.workflows}
            totalCount={payload.totalCount}
            pinnedWorkflowIds={payload.pinnedWorkflowIds}
            allowPinning={payload.allowPinning}
            owner={owner}
            repo={repo}
            selectedWorkflowFile={filename}
            showDeployments={payload.showDeployments}
            showAttestations={payload.showAttestations}
            showRunners={payload.showRunners}
            showUsageMetrics={payload.showUsageMetrics}
            refreshWorkflows={refetch}
          />
        </PageLayout.Pane>
        <PageLayout.Content as="div">
          <Outlet />
        </PageLayout.Content>
      </PageLayout>
    </div>
  )
}
