import {DataTable, Table} from '@primer/react/experimental'
import {Link} from '@primer/react'
import type {WorkflowRun} from '../views/models'

interface WorkflowRunsTableProps {
  workflowRuns: WorkflowRun[]
  title: string
  caption?: string
}

export function WorkflowRunsTable({workflowRuns, title}: WorkflowRunsTableProps) {
  return (
    <Table.Container>
      <Table.Title as="h2" id="workflow-runs-table">
        {title}
      </Table.Title>
      <DataTable
        aria-labelledby="workflow-runs-table"
        data={workflowRuns}
        columns={[
          {
            header: 'Name',
            field: 'name',
            rowHeader: true,
            renderCell: row => <Link href={`actions/runs/${row.id}`}>{row.name}</Link>,
          },
          {
            header: 'Run #',
            field: 'runNumber',
          },
          {
            header: 'Workflow',
            field: 'workflowFilePath',
          },
        ]}
      />
    </Table.Container>
  )
}
